function renderSelectedTraceSessionContent(idx) {
  const ledger = dashboardState?.active_model_call_ledger || [];
  const c = ledger[idx];
  if (!c) return;
  const titleEl = document.getElementById("sri-report-title");
  if (titleEl) {
    titleEl.textContent = `🔎 Phiên #${idx + 1} [${c.call_id}] · ${c.stage}${c.sub_task_id ? " (" + c.sub_task_id + ")" : ""} · Model: ${c.model}`;
  }
  const mdEl = document.getElementById("sri-markdown-content");
  if (mdEl) {
    mdEl.textContent = [
      `# 🔎 Chi Tiết Phiên Gọi Model #${idx + 1} (${c.call_id}) — Task ${c.task_key}`,
      `- **Thời gian:** \`${c.timestamp}\` · **Thời lượng:** \`${c.duration_ms} ms\``,
      `- **Stage:** \`${c.stage}\` · **Sub-Task:** \`${c.sub_task_id || "-"}\``,
      `- **Role:** \`${c.role}\` · **Model & Runner:** \`${c.model}\` (\`${c.runner}\`) · **Session ID:** \`${c.session_id || "-"}\``,
      `- **Target Repo & Branch:** \`${c.target_repo}\` (\`⎇ ${c.target_branch}\`) · **Repo Memory:** \`${c.repo_memory_status || "-"}\``,
      `- **Trạng thái thật:** \`${c.status}\``,
      ``,
      `## 1. System Prompt Đã Gửi`,
      "```text",
      c.system_prompt || "(Trống)",
      "```",
      ``,
      `## 2. User Prompt Đã Gửi`,
      "```text",
      c.user_prompt || "(Trống)",
      "```",
    ].join("\n");
  }
  const codeEl = document.getElementById("sri-code-demo-content");
  if (codeEl) {
    codeEl.textContent =
      `// === RAW MODEL RESPONSE (${c.call_id} · ${c.model} · ${c.status} · ${c.duration_ms}ms) ===\n` +
      (c.raw_response || "(Không có dữ liệu trả về)");
  }
}

function renderPerTaskModelCallLedger() {
  if (!dashboardState) return;
  const cyclesEl = document.getElementById("autopilot-cycles");
  const ledger = dashboardState.active_model_call_ledger || [];
  if (cyclesEl) {
    const activeKey = dashboardState.active_task_key || selectedChainKey || "";
    if (ledger.length > 0) {
      const rowsHtml = ledger
        .map((c, idx) => {
          const stStr = String(c.status || "").toUpperCase();
          const tone = stStr === "REAL_LLM_OK" ? "green" : stStr === "LLM_ERROR" ? "red" : "amber";
          const subTag = c.sub_task_id ? ` · ${c.sub_task_id}` : "";
          const durSec = (Number(c.duration_ms || 0) / 1000).toFixed(1);
          return `
            <div class="ap-row clickable" onclick="inspectTraceCallEntry(${idx})" title="Click để xem chi tiết Prompt &amp; Raw Response của phiên ${escapeAttr(c.call_id || "")}">
              <span><b>#${idx + 1} [${escapeHtml(c.stage || "S1-S3")}${escapeHtml(subTag)}]</b> 🤖 <code>${escapeHtml(c.model || "")}</code>: <span class="ap-status-word ${tone}">${escapeHtml(c.status || "REAL_LLM_OK")}</span></span>
              <span class="ap-row-actions">
                <span>📦 ${escapeHtml(c.target_repo || "")} · ⏱ ${durSec}s · ${escapeHtml(c.timestamp || "")}</span>
              </span>
            </div>
          `;
        })
        .join("");

      cyclesEl.innerHTML = `
        <div class="ap-cycle-block">
          <div class="ap-cycle-hdr">
            <span>🔎 Sổ Cái Phiên Gọi Model Của ${escapeHtml(activeKey)}</span>
            <span>${ledger.length} phiên</span>
          </div>
          ${rowsHtml}
        </div>
      `;
    } else {
      cyclesEl.innerHTML = `
        <div class="ap-cycle-block">
          <div class="ap-cycle-hdr">
            <span>🔎 Sổ Cái Phiên Gọi Model Của ${escapeHtml(activeKey)}</span>
            <span>0 phiên</span>
          </div>
          <div class="ap-row"><span>Chưa có phiên gọi LLM nào cho ${escapeHtml(activeKey)}.</span></div>
        </div>
      `;
    }
  }

  const totalEl = document.getElementById("autopilot-total-val");
  if (totalEl) {
    const totalMs = ledger.reduce((acc, c) => acc + Number(c.duration_ms || 0), 0);
    totalEl.textContent = `${ledger.length} phiên gọi Model · ${(totalMs / 1000).toFixed(1)}s`;
  }
}

function inspectTraceCallEntry(idx) {
  selectedTraceSessionIndex = idx;
  selectedReportTab = "TRACE";
  userLockedReportTab = true;
  renderStepReportInspector();
}

function syncModalRepoByTitleAndBranchHint(title) {
  if (!title || !dashboardState) return;
  const lower = title.toLowerCase();
  const repos = dashboardState.available_repos || [];
  const brMatch = title.match(/(?:branch|nhánh)\s+[`'"]?([a-zA-Z0-9._/\-]+)/i);
  const brHint = brMatch ? brMatch[1].trim().toLowerCase() : "";

  let matchedPaths = [];
  if (brHint && brHint !== "main" && brHint !== "master" && brHint !== "develop") {
    matchedPaths = repos
      .filter((r) => String(r.branch || "").toLowerCase() === brHint)
      .map((r) => r.path);
  }
  if (matchedPaths.length === 0) {
    matchedPaths = repos
      .filter((r) => {
        const base = formatRepoBasename(r.path).toLowerCase();
        return base && base !== "package" && base !== "data-hub" && lower.includes(base);
      })
      .map((r) => r.path);
  }
  if (matchedPaths.length > 0) {
    const repoSel = document.getElementById("inp-task-repo");
    if (repoSel) repoSel.value = matchedPaths[0];
    document.querySelectorAll('input[name="affected_repo_chk"]').forEach((chk) => {
      chk.checked = matchedPaths.includes(chk.value);
    });
  }
}
